final:
class DivZero:
    a: int

def safe_div(a: int, b: int) -> int fail DivZero:
    """Floor division of a by b. Dividing by zero fails with DivZero carrying the numerator a."""
    ex safe_div(7, 2) == 3
    ex safe_div(-7, 2) == -4
    ex safe_div(7, 0) == Err(DivZero(a=7))
    if b != 0:
        return a // b
    fail DivZero(a=a)
